const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)],world=q('#world');let scale=1,panX=0,panY=0,z=2;
function render(){world.style.transform=`translate(${panX}px,${panY}px) scale(${scale})`;q('#zoom-level').textContent=Math.round(scale*100)+'%'}
function fit(){if(innerWidth<=760)return;const cards=qa('.card:not([hidden])');let maxX=1300,maxY=650,minX=0,minY=0;cards.forEach(c=>{minX=Math.min(minX,c.offsetLeft-30);minY=Math.min(minY,c.offsetTop-90);maxX=Math.max(maxX,c.offsetLeft+c.offsetWidth+30);maxY=Math.max(maxY,c.offsetTop+c.offsetHeight+80)});scale=Math.min((innerWidth-30)/(maxX-minX),(innerHeight-100)/(maxY-minY),1);panX=(innerWidth-(maxX-minX)*scale)/2-minX*scale;panY=75-minY*scale;render()}
