q('#goto').onchange=e=>{openCard(e.target.value);e.target.value=''};q('#fit').onclick=fit;q('#minimize').onclick=()=>qa('.card').forEach(c=>c.hidden=true);q('#random').onclick=()=>{const cards=qa('.card');openCard(cards[Math.floor(Math.random()*cards.length)].id)};q('#arrange').onclick=()=>{qa('.card:not([hidden])').forEach((c,i)=>{c.style.left=(60+(i%3)*410)+'px';c.style.top=(120+Math.floor(i/3)*520)+'px'});fit()};q('#zoom-in').onclick=()=>{scale=Math.min(1.8,scale+.1);render()};q('#zoom-out').onclick=()=>{scale=Math.max(.25,scale-.1);render()};window.addEventListener('resize',fit);
let dragging=null;q('#viewport').addEventListener('pointerdown',e=>{if(innerWidth<=760||e.target.closest('button,a,input,textarea,select'))return;const header=e.target.closest('.card header'),card=header?.closest('.card');if(!card&&e.target.closest('.card'))return;dragging={id:e.pointerId,x:e.clientX,y:e.clientY,card,left:card?card.offsetLeft:panX,top:card?card.offsetTop:panY};if(card)card.style.zIndex=++z;e.currentTarget.setPointerCapture(e.pointerId)});q('#viewport').addEventListener('pointermove',e=>{if(!dragging)return;const d=dragging,dx=e.clientX-d.x,dy=e.clientY-d.y;if(d.card){d.card.style.left=d.left+dx/scale+'px';d.card.style.top=d.top+dy/scale+'px'}else{panX=d.left+dx;panY=d.top+dy;render()}});q('#viewport').addEventListener('pointerup',()=>dragging=null);q('#viewport').addEventListener('pointercancel',()=>dragging=null);
