let time=1500,clock=null,end=0;function showTime(){q('#timer').textContent=Math.floor(time/60).toString().padStart(2,'0')+':'+(time%60).toString().padStart(2,'0')}function pause(){clearInterval(clock);clock=null;q('#timer-toggle').textContent='Resume focus'}q('#timer-toggle').onclick=()=>{if(clock){pause();return}if(time<=0)time=1500;end=Date.now()+time*1000;q('#timer-toggle').textContent='Pause';q('#timer-status').textContent='Focus time. You have got this.';clock=setInterval(()=>{time=Math.max(0,Math.ceil((end-Date.now())/1000));showTime();if(!time){pause();q('#timer-toggle').textContent='Start focus';q('#timer-status').textContent='Session complete. Take a short break.'}},250)};q('#timer-reset').onclick=()=>{pause();time=1500;showTime();q('#timer-toggle').textContent='Start focus';q('#timer-status').textContent='A 25-minute break from distractions.'};
let chosen=[],moves=0,matched=0,locked=false,gameVersion=0;function newGame(){const version=++gameVersion;chosen=[];moves=0;matched=0;locked=false;q('#moves').textContent=0;q('#game-status').textContent='';const symbols=['★','◉','◆','♣','☀','♥'];const deck=[...symbols,...symbols];for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}q('#game').replaceChildren();deck.forEach((symbol,i)=>{const b=document.createElement('button');b.textContent='?';b.setAttribute('aria-label','Reveal card '+(i+1));b.onclick=()=>{if(locked||b.disabled||chosen.some(v=>v.b===b))return;b.textContent=symbol;b.setAttribute('aria-label',symbol);chosen.push({b,symbol});if(chosen.length===2){moves++;q('#moves').textContent=moves;const [a,c]=chosen;if(a.symbol===c.symbol){a.b.disabled=c.b.disabled=true;a.b.classList.add('matched');c.b.classList.add('matched');matched+=2;chosen=[];if(matched===12){let best=moves;try{best=Math.min(Number(localStorage.getItem('ap-best'))||999,moves);localStorage.setItem('ap-best',best)}catch{}q('#game-status').textContent=`All matched in ${moves} moves! Best: ${best}.`}}else{locked=true;setTimeout(()=>{if(version!==gameVersion)return;a.b.textContent=c.b.textContent='?';a.b.setAttribute('aria-label','Reveal card');c.b.setAttribute('aria-label','Reveal card');chosen=[];locked=false},750)}}};q('#game').append(b)})}q('#new-game').onclick=newGame;newGame();
let audio=null;q('#sound').onclick=async()=>{try{if(!audio){audio=new AudioContext();const gain=audio.createGain();gain.gain.value=.018;gain.connect(audio.destination);[130.81,164.81,196].forEach(f=>{const osc=audio.createOscillator();osc.type='sine';osc.frequency.value=f;osc.connect(gain);osc.start()})}else if(audio.state==='running'){await audio.suspend()}else{await audio.resume()}const on=audio.state==='running';q('#sound').textContent=on?'♫ Sound on':'♫ Sound off';q('#sound').setAttribute('aria-pressed',String(on))}catch{q('#sound').textContent='Sound unavailable'}};fit();
